def seed_builtin_templates(apps, schema_editor):
    """Give a fresh install useful starting points without putting presets in the admin."""
    from apps.policies.presets import presets

    PolicyTemplate = apps.get_model("policies", "PolicyTemplate")
    for preset in presets():
        PolicyTemplate.objects.update_or_create(
            name=preset["name"],
            defaults={
                "description": preset["description"],
                "document": preset["document"],
                "is_builtin": True,
            },
        )


